def _seed():
    init_db()
    session = SessionLocal()
    now = utcnow()
    sol = Token(mint="SolBoardMint1111111111111111111111111111", symbol="SOLX", chain="sol", source="poll", first_seen_at=now, migrated_at=now)
    rh = Token(
        mint="0xabc0000000000000000000000000000000000001",
        symbol="RHX",
        chain="robinhood",
        source="rh_trenches",
        first_seen_at=now,
        migrated_at=now,
    )
    sol.research = Research(p_good=0.71, features_json="{}")
    rh.research = Research(p_good=0.66, features_json="{}")
    session.add_all([sol, rh])
    session.flush()
    session.add(Outcome(token_id=sol.id, t0_mcap=69000, max_mcap=80000, multiple=1.16, label=0, last_liq=80000))
    session.add(Outcome(token_id=rh.id, t0_mcap=40000, max_mcap=50000, multiple=1.25, label=0, last_liq=50000))
    session.commit()
    session.close()


def test_separate_dashboard_pages():
    """Root routes serve the oversight desk; Classic boards are retired."""
    sol_page = Path("launchfinder/static/desk.html").read_text()
    rh_page = Path("launchfinder/static/desk-rh.html").read_text()
    assert 'data-chain="sol"' in sol_page
    assert 'data-chain="robinhood"' in rh_page
    assert "Classic" not in sol_page and "Classic" not in rh_page
    assert "seg-version" not in sol_page and "seg-version" not in rh_page
    assert 'href="/"' in sol_page and 'href="/rh"' in sol_page
    assert 'data-desk="picks"' in sol_page and 'data-desk="learn"' in sol_page
    assert 'data-desk="live"' in sol_page and 'data-desk="board"' in sol_page
    assert asyncio.run(index()).path.name == "desk.html"
    assert asyncio.run(robinhood_index()).path.name == "desk-rh.html"


