def test_token_card_exposes_rh_launchpad():
    init_db()
    session = SessionLocal()
    now = utcnow()
    pons = Token(
        mint="0xpad0000000000000000000000000000000000001",
        symbol="PAD",
        chain="robinhood",
        source="rh_pons",
        first_seen_at=now,
        migrated_at=now,
    )
    pons.research = Research(p_good=0.55, features_json="{}", raw_json='{"gmgn": {"launchpad": "pons"}}')
    dex = Token(
        mint="0xpad0000000000000000000000000000000000002",
        symbol="DEX",
        chain="robinhood",
        source="rh_dex",
        first_seen_at=now,
        migrated_at=now,
    )
    dex.research = Research(p_good=0.4, features_json="{}")
    session.add_all([pons, dex])
    session.commit()
    assert token_card(pons)["launchpad"] == "pons"
    assert token_card(dex)["launchpad"] == "dex"
    session.close()


def test_token_card_fills_zero_multiple_from_t0():
    # Live KFC: t0 == max $146k but outcome.multiple stayed 0, so the
    # desk showed 0.0x on a $40k book.
    kfc = Token(
        mint="0xkfczeromultiple00000000000000000000001",
        symbol="KFC",
        chain="robinhood",
        source="rh_pons",
        first_seen_at=utcnow(),
    )
    kfc.research = Research(p_good=0.82, holder_count=1222, features_json="{}")
    kfc.outcome = Outcome(t0_mcap=146_816.0, max_mcap=146_816.0, multiple=0.0, last_liq=40_826.0)
    card = token_card(kfc)
    assert abs(card["multiple"] - 1.0) < 1e-6
    # Stored 2x still wins over the fallback.
    kfc.outcome.multiple = 2.4
    assert abs(token_card(kfc)["multiple"] - 2.4) < 1e-6


def test_token_card_exposes_associated_dev_x():
    from launchfinder.serialize import associated_dev_handle, token_card

    profile = Token(
        mint="DevXProfile11111111111111111111111111111",
        symbol="DEVX",
        chain="sol",
        twitter="https://x.com/launchonquick",
        website="https://quicklaunch.fun/",
        first_seen_at=utcnow(),
    )
    profile.research = Research(p_good=0.55, features_json="{}", twitter_handle="launchonquick")
    assert associated_dev_handle(profile, profile.research) == ""
    card = token_card(profile)
    assert card["twitter_handle"] == "launchonquick"
    assert card["dev_handle"] == ""
    assert card["has_dev_x"] is False
    profile.research.twitter_followers = 4200
    profile.research.twitter_tweets = 180
    profile.research.twitter_age_days = 800
    profile.research.raw_json = '{"twitter": {"bio": "building $DEVX"}}'
    profiled = token_card(profile)
    assert profiled["twitter_tweets"] == 180
    assert profiled["twitter_bio_match"] is True
    assert profiled["twitter_age_days"] == 800

    creator = Token(
        mint="DevXCreator11111111111111111111111111111",
        symbol="CRE8",
        chain="sol",
        twitter="https://x.com/SomePaste/status/1",
        website="https://example.com/",
        first_seen_at=utcnow(),
    )
    creator.research = Research(
        p_good=0.55,
        features_json="{}",
        twitter_handle="SomePaste",
        raw_json='{"user": {"x_username": "realdevwallet"}}',
    )
    assert associated_dev_handle(creator, creator.research) == "realdevwallet"
    creator_card = token_card(creator)
    assert creator_card["dev_handle"] == "realdevwallet"
    assert creator_card["twitter_handle"] == ""
    assert creator_card["has_dev_x"] is True

    twin = Token(
        mint="DevXTwin11111111111111111111111111111111",
        symbol="TWIN",
        chain="sol",
        twitter="https://x.com/AragornSol/status/2099235852543315992",
        website="https://twine.auction/a/twin-zwjg",
        first_seen_at=utcnow(),
    )
    twin.research = Research(p_good=0.92, features_json="{}", twitter_handle="AragornSol")
    assert associated_dev_handle(twin, twin.research) == ""
    assert token_card(twin)["has_dev_x"] is False

    nasa = Token(
        mint="DevXNasa11111111111111111111111111111111",
        symbol="NASA",
        chain="sol",
        twitter="https://x.com/NASA",
        website="https://www.nasa.gov/",
        first_seen_at=utcnow(),
    )
    nasa.research = Research(
        p_good=0.33,
        features_json="{}",
        twitter_handle="NASA",
        twitter_followers=92_390_162,
        twitter_age_days=6843,
        twitter_verified=True,
        risk_flags_json='["Claimed celebrity/brand X — not this launch"]',
    )
    assert associated_dev_handle(nasa, nasa.research) == ""
    nasa_card = token_card(nasa)
    assert nasa_card["has_dev_x"] is False
    assert nasa_card["claimed_brand_x"] is True
    assert nasa_card["twitter_handle"] == "NASA"

    from launchfinder.serialize import display_token_x

    assert display_token_x("amemecoinrh", "") == "amemecoinrh"
    assert display_token_x("projectx", "realdevwallet") == "projectx"
    assert display_token_x("forestmansol555", "forestmansol555") == ""
    assert display_token_x("ForestManSol555", "forestmansol555") == ""

    same = Token(
        mint="DevXSame1111111111111111111111111111111",
        symbol="SAME",
        chain="sol",
        twitter="https://x.com/forestmansol555",
        website="https://example.com/",
        first_seen_at=utcnow(),
    )
    same.research = Research(
        p_good=0.92,
        features_json="{}",
        twitter_handle="forestmansol555",
        twitter_followers=3702,
        twitter_age_days=5239,
        raw_json='{"user": {"x_username": "forestmansol555"}}',
    )
    assert associated_dev_handle(same, same.research) == "forestmansol555"
    same_card = token_card(same)
    assert same_card["dev_handle"] == "forestmansol555"
    assert same_card["twitter_handle"] == ""
    assert same_card["has_dev_x"] is True
    assert same_card["claimed_brand_x"] is False


def test_dashboards_and_chain_isolation():
    _seed()
    sol_tokens = asyncio.run(list_tokens(limit=80, min_score=0, historical=None, labeled=None, fresh_hours=168, chain="sol"))
    rh_tokens = asyncio.run(list_tokens(limit=80, min_score=0, historical=None, labeled=None, fresh_hours=168, chain="robinhood"))
    assert any(t["symbol"] == "SOLX" for t in sol_tokens)
    assert all(t["chain"] == "sol" for t in sol_tokens)
    assert any(t["symbol"] == "RHX" for t in rh_tokens)
    assert all(t["chain"] == "robinhood" for t in rh_tokens)
    assert all(t["symbol"] != "SOLX" for t in rh_tokens)
    rh_status = asyncio.run(status(chain="robinhood"))
    assert rh_status["chain"] == "robinhood"
    assert rh_status["tokens"] >= 1


def test_rh_live_desk_keeps_catchup_by_first_seen():
    # Trench open is 30h ago (fails Solana 18h + the /rh 12h migrated_at cut)
    # but we ingested it just now. Live-only /rh must still list it.
    init_db()
    session = SessionLocal()
    now = utcnow()
    zazu = Token(
        mint="0xzazulivedesk00000000000000000000000001",
        symbol="ZAZU",
        chain="robinhood",
        source="rh_trenches",
        first_seen_at=now,
        migrated_at=now - timedelta(hours=30),
        created_at_chain=now - timedelta(hours=36),
        is_historical=False,
    )
    zazu.research = Research(p_good=0.55, features_json="{}")
    session.add(zazu)
    session.flush()
    session.add(Outcome(token_id=zazu.id, t0_mcap=33639, max_mcap=33639, multiple=1.0, last_liq=0.0))
    session.commit()
    session.close()

    cards = asyncio.run(
        list_tokens(limit=80, min_score=0, historical=False, labeled=None, fresh_hours=12, chain="robinhood")
    )
    assert any(t["symbol"] == "ZAZU" for t in cards)


def test_rh_live_desk_lists_real_books_before_leftover_flood():
    # Live 20:40: a 12-name trench flood of $0 Fortnite/TESTED clones
    # filled /api/tokens; ZOINBASE $34k sat under them. Real books first.
    init_db()
    session = SessionLocal()
    now = utcnow()
    leftover = Token(
        mint="0xfortnitedesk00000000000000000000000001",
        symbol="FORTNITE",
        chain="robinhood",
        source="rh_trenches",
        first_seen_at=now,
        migrated_at=now,
        is_historical=False,
    )
    leftover.research = Research(p_good=0.43, features_json="{}")
    real = Token(
        mint="0xzoinbasedesk00000000000000000000000001",
        symbol="ZOINBASE",
        chain="robinhood",
        source="rh_trenches",
        first_seen_at=now - timedelta(minutes=2),
        migrated_at=now - timedelta(minutes=2),
        is_historical=False,
    )
    real.research = Research(p_good=0.71, features_json="{}")
    session.add_all([leftover, real])
    session.flush()
    session.add(Outcome(token_id=leftover.id, t0_mcap=40_000.0, max_mcap=40_000.0, multiple=1.0, last_liq=0.0))
    session.add(Outcome(token_id=real.id, t0_mcap=33_000.0, max_mcap=34_500.0, multiple=1.0, last_liq=34_518.0))
    session.commit()
    session.close()

    cards = asyncio.run(
        list_tokens(limit=80, min_score=0, historical=False, labeled=None, fresh_hours=12, chain="robinhood")
    )
    symbols = [t["symbol"] for t in cards]
    assert "ZOINBASE" in symbols
    assert "FORTNITE" in symbols
    assert symbols.index("ZOINBASE") < symbols.index("FORTNITE")


