def test_sol_live_hunt_caps_fat_leftover_fdv_flood():
    # Live 08:20: Laptop / Pill sat under NTDA / ClaudeAI / CLAWDHOOD /
    # NIKE $4–15M / ~1.0× that filled the 4h 80. leftover-size already
    # ranks them down; they still occupy the page. Cap fat leftovers.
    # Do not leftover-sort 2×+ (WOTF-class stays).
    from launchfinder.scoring.outcomes import SOL_HUNT_FAT_LEFTOVER_CAP

    init_db()
    session = SessionLocal()
    now = utcnow()
    real = Token(
        mint="SolLaptopHuntKeepMint1111111111111111",
        symbol="LAPKEEP",
        chain="sol",
        source="poll",
        first_seen_at=now - timedelta(minutes=20),
        migrated_at=now - timedelta(minutes=20),
        is_historical=False,
    )
    real.research = Research(p_good=0.87, holder_count=344, features_json="{}")
    runner = Token(
        mint="SolWotfHuntKeep2xMint1111111111111111",
        symbol="WOTFKEEP",
        chain="sol",
        source="poll",
        first_seen_at=now - timedelta(minutes=30),
        migrated_at=now - timedelta(minutes=30),
        is_historical=False,
    )
    runner.research = Research(p_good=0.37, holder_count=80, features_json="{}")
    session.add_all([real, runner])
    session.flush()
    session.add(Outcome(token_id=real.id, t0_mcap=40_834.0, max_mcap=77_269.0, multiple=1.89, last_liq=28_000.0, last_mcap=77_269.0))
    session.add(Outcome(token_id=runner.id, t0_mcap=4_480_000.0, max_mcap=11_700_000.0, multiple=2.61, last_liq=280_000.0, last_mcap=11_700_000.0))
    leftovers = []
    for i in range(12):
        tok = Token(
            mint=f"SolFatHuntFloodMint{i:02d}111111111111111",
            symbol=f"FAT{i:02d}",
            chain="sol",
            source="poll",
            first_seen_at=now - timedelta(minutes=i),
            migrated_at=now - timedelta(minutes=i),
            is_historical=False,
        )
        tok.research = Research(p_good=0.20, holder_count=20, features_json="{}")
        leftovers.append(tok)
    session.add_all(leftovers)
    session.flush()
    for i, tok in enumerate(leftovers):
        session.add(
            Outcome(
                token_id=tok.id,
                t0_mcap=5_000_000.0 + i * 1000,
                max_mcap=5_200_000.0 + i * 1000,
                multiple=1.04,
                last_liq=90_000.0,
                last_mcap=5_200_000.0 + i * 1000,
            )
        )
    session.commit()
    session.close()

    cards = asyncio.run(
        list_tokens(limit=80, min_score=0, historical=False, labeled=None, fresh_hours=4, chain="sol")
    )
    symbols = [t["symbol"] for t in cards]
    fat = [s for s in symbols if s.startswith("FAT")]
    assert "LAPKEEP" in symbols
    assert "WOTFKEEP" in symbols
    assert len(fat) <= SOL_HUNT_FAT_LEFTOVER_CAP
    assert symbols.index("LAPKEEP") < symbols.index(fat[0])


