def test_labeled_5x_dump_off_ath_lowers_score_not_membership():
    # Live BELIEVE: honest 28× from $25k, then last print $89k.
    # Stall honesty skips labeled cards, so the ATH dump has to fade
    # the displayed score without dropping confirmed-5× membership.
    from launchfinder.app import runners
    from launchfinder.models import Snapshot
    from launchfinder.serialize import apply_ath_dump_honesty, token_card, token_detail

    faded = apply_ath_dump_honesty(
        {
            "label": 1,
            "multiple": 28.46,
            "p_good": 0.78,
            "score": 78.0,
            "max_mcap": 702_855.0,
            "last_mcap": 88_928.0,
            "risk_flags": ["X account created very recently"],
        }
    )
    assert faded["p_good"] == 0.35
    assert faded["score"] == 35.0
    assert any("Dumped off ATH" in flag for flag in faded["risk_flags"])

    held = apply_ath_dump_honesty(
        {
            "label": 1,
            "multiple": 28.46,
            "p_good": 0.78,
            "score": 78.0,
            "max_mcap": 702_855.0,
            "last_mcap": 500_000.0,
            "risk_flags": [],
        }
    )
    assert held["p_good"] == 0.78

    init_db()
    session = SessionLocal()
    now = utcnow()
    token = Token(
        mint="0xbelieveathdump000000000000000000000001",
        symbol="BELIEVE",
        chain="robinhood",
        source="rh_trenches",
        first_seen_at=now - timedelta(hours=8),
        migrated_at=now - timedelta(hours=8),
        created_at_chain=now - timedelta(hours=8),
        is_historical=False,
    )
    token.research = Research(
        p_good=0.78,
        heuristic_p=0.78,
        holder_count=860,
        features_json="{}",
        risk_flags_json='["X account created very recently"]',
    )
    session.add(token)
    session.flush()
    session.add(
        Outcome(
            token_id=token.id,
            t0_mcap=24_697.0,
            max_mcap=702_855.0,
            multiple=28.46,
            label=1,
            last_liq=67_125.0,
            t24h_mcap=88_928.0,
        )
    )
    session.add(
        Snapshot(
            token_id=token.id,
            kind="t0",
            taken_at=now - timedelta(hours=8),
            mcap_usd=24_697.0,
            liquidity_usd=24_435.0,
            volume_h1=9_000.0,
            p_good=0.78,
        )
    )
    session.add(
        Snapshot(
            token_id=token.id,
            kind="t15m",
            taken_at=now - timedelta(hours=7, minutes=45),
            mcap_usd=702_855.0,
            liquidity_usd=222_613.0,
            volume_h1=80_000.0,
            p_good=0.78,
        )
    )
    session.add(
        Snapshot(
            token_id=token.id,
            kind="post",
            taken_at=now - timedelta(hours=2),
            mcap_usd=88_928.0,
            liquidity_usd=67_125.0,
            volume_h1=5_000.0,
            p_good=0.78,
        )
    )
    session.commit()
    session.refresh(token)
    card = token_card(token)
    assert abs(card["p_good"] - 0.35) < 1e-6
    assert card["score"] == 35.0
    assert abs(card["last_mcap"] - 88_928.0) < 1e-6
    detail = token_detail(token)
    assert abs(detail["p_good"] - 0.35) < 1e-6
    assert any("Dumped off ATH" in flag for flag in detail["risk_flags"])
    session.close()

    board = asyncio.run(runners(min_multiple=5.0, chain="robinhood"))
    hit = [r for r in board["items"] if r["mint"] == "0xbelieveathdump000000000000000000000001"]
    assert hit
    assert hit[0]["entry_p"] == 0.78
    assert hit[0]["flagged_at_entry"] is True

    from launchfinder.app import doing_well

    hot = asyncio.run(doing_well(chain="robinhood"))
    faded = [r for r in hot["items"] if r["mint"] == "0xbelieveathdump000000000000000000000001"]
    assert faded == []


def test_models_are_per_chain():
    init_db()
    session = SessionLocal()
    try:
        sol = get_or_create_model(session, chain="sol")
        rh = get_or_create_model(session, chain="robinhood")
        assert sol.id != rh.id
        sol_before, rh_before = sol.n_train, rh.n_train
        features = {n: 0.0 for n in FEATURE_NAMES}
        features["twitter_followers_n"] = 1.0
        online_update(session, features, 1, chain="robinhood")
        session.flush()
        session.refresh(sol)
        session.refresh(rh)
        assert rh.n_train == rh_before + 1
        assert sol.n_train == sol_before
    finally:
        session.close()


