    session.close()
    rh_poll._watch_preview = []
    data = asyncio.run(graduating_soon(chain="robinhood"))
    symbols = [r["symbol"] for r in data["graduating_soon"]]
    assert "HOFRESH" in symbols
    assert "EQUINFZ" not in symbols


